#include <iostream>
#include <stdexcept>
#include <vector>

struct Fill {
    int id;
    long long delta;
    long long price;
    long long fee;
};
enum class ApplyStatus { applied, invalid, duplicate, capacity, position, funds };

class CheckedLedger {
    long long cash_;
    long long position_ = 0;
    std::vector<int> ids_;
public:
    explicit CheckedLedger(long long initial_cash) : cash_{initial_cash} {
        if (initial_cash < 0 || initial_cash > 1000000000LL) {
            throw std::invalid_argument("initial cash out of range");
        }
    }
    long long cash() const noexcept { return cash_; }
    long long position() const noexcept { return position_; }
    std::size_t count() const noexcept { return ids_.size(); }
    ApplyStatus apply(const Fill& fill) {
        if (fill.id <= 0 || fill.delta == 0 || fill.delta < -1000000LL || fill.delta > 1000000LL
            || fill.price < 1 || fill.price > 1000000LL || fill.fee < 0 || fill.fee > 1000000LL) {
            return ApplyStatus::invalid;
        }
        for (const int id : ids_) {
            if (id == fill.id) return ApplyStatus::duplicate;
        }
        if (ids_.size() >= 1000) return ApplyStatus::capacity;
        const long long next_position = position_ + fill.delta;
        if (next_position < 0 || next_position > 1000000LL) return ApplyStatus::position;
        const long long next_cash = cash_ - fill.delta * fill.price - fill.fee;
        if (next_cash < 0) return ApplyStatus::funds;
        ids_.push_back(fill.id); // May throw; scalar state not changed yet.
        cash_ = next_cash;       // Nonthrowing scalar commit after successful int append.
        position_ = next_position;
        return ApplyStatus::applied;
    }
};

int main() {
    CheckedLedger book{10000};
    std::cout << (book.apply({1, 5, 1000, 2}) == ApplyStatus::applied) << '\n';
    std::cout << (book.apply({1, 5, 1000, 2}) == ApplyStatus::duplicate) << '\n';
    std::cout << (book.apply({2, -9, 1100, 1}) == ApplyStatus::position) << '\n';
    std::cout << (book.apply({3, -2, 1100, 1}) == ApplyStatus::applied) << '\n';
    std::cout << book.cash() << ' ' << book.position() << ' ' << book.count() << '\n';
}

#include <iostream>
#include <stdexcept>
