    long long position() const noexcept { return position_; }
    std::size_t count() const noexcept { return ids_.size(); }
    ApplyStatus apply(const Fill& fill) {
        if (fill.id <= 0 || fill.delta == 0 || fill.delta < -1000000LL || fill.delta > 1000000LL
            || fill.price < 1 || fill.price > 1000000LL || fill.fee < 0 || fill.fee > 1000000LL) {
            return ApplyStatus::invalid;
