int main() {
    CheckedLedger book{10000};
    if (book.apply({1,5,1000,2}) != ApplyStatus::applied) return 1;
    const auto cash = book.cash();
    const auto quantity = book.position();
    const auto count = book.count();
    if (book.apply({2,6,1000,0}) != ApplyStatus::funds) return 2;
    if (book.cash()!=cash || book.position()!=quantity || book.count()!=count) return 3;
    if (book.apply({2,-2,1100,1}) != ApplyStatus::applied) return 4;
    // Independent confirmed-fill sums in this fixed trace, not a matching mirror update loop.
    const long long reference_cash = 10000 - 5*1000 - 2 + 2*1100 - 1;
    const long long reference_position = 5 - 2;
    if (book.cash()!=reference_cash || book.position()!=reference_position || book.count()!=2) return 5;
    std::cout << "ledger reconciled " << book.cash() << ' ' << book.position() << '\n';
}
